import declarationJson from '../../../tasks/publish-pages/task.json' with { type: 'json' };
import updateJson from '../../../../claudinite-lifecycle/tasks/update/task.json' with { type: 'json' };
import {
  normalizeTaskDeclaration, isScheduledTask,
